insert into growth.playbooks (task_type, version, name, instructions, is_champion) values
('shorts_script', 1, '쇼츠·릴스 대본 v1', '1) 0~2초 훅: 결과·반전·질문 중 하나로 시작(인사 금지). 2) 3~5초 안에 "왜 끝까지 봐야 하는지" 약속. 3) 본문은 2~3초 단위 컷, 화면 텍스트는 한 줄 12자 이내. 4) 마지막 2초에 다음 행동(댓글·저장·프로필 링크) 한 가지만. 5) 대본은 [시간] 화면 / 대사 / 자막 / 효과음 4칸 표로. 6) 채널 톤 유지: 쌍둥이루지는 밝고 다정, 아무도 놀리지 않음.', true),
('ad_plan', 1, '제품 광고 기획 v1', '1) 한 문장 핵심 메시지(누가, 어떤 문제, 왜 이 제품). 2) 타깃 1명 페르소나와 시청 상황. 3) 기획→대사→연출 순서로 완성도 점검: 대사는 소리 내어 3초 안에 읽히는 길이, 연출은 컷마다 카메라·조명·소품 지정. 4) 훅 3안 A/B 제시. 5) 플랫폼별 길이(릴스 15~30초, 쇼츠 30~60초, 광고 6/15초 컷다운). 6) 표시광고법: 최상급·비교 표현은 근거와 날짜 명시.', true),
('image_prompt', 1, '이미지 생성 프롬프트 v1', '1) 고급스럽고 현실적인 연출: 렌즈(mm), 조명 방향·색온도, 재질, 피사계 심도 명시. 2) 강한 시각적 상상력: 한 장면에 하나의 놀라운 요소. 3) 캐릭터 일관성: 루루=검은 생머리 양갈래 땋은 머리·주황 머리끈·노란 안경, 지지=갈색 앞머리 양갈래·연두 머리끈·핑크 안경. 4) 한글 글자는 이미지에 넣지 않고 편집에서 합성. 5) 실존 인물·브랜드 로고 사용 금지.', true),
('lecture', 1, '강의 콘텐츠 v1', '1) 한 강의 = 한 가지 결과물(수강생이 끝나고 만들 수 있는 것). 2) 구성: 사례 → 원리 → 따라하기 → 과제. 3) 모든 예시는 자신의 채널(쌍둥이루지, 조안나, 해피봄봄, 달달영심이) 실제 영상에서 가져와 재활용. 4) 강의 클립은 쇼츠로 잘라 쓸 수 있게 60초 단위 소단원. 5) 최신 사례는 날짜와 출처 표기.', true);
insert into growth.learnings (task_type, insight, tags, source) values
('all', '모든 답변은 영상 제작·광고 기획에 바로 쓸 수 있는 산출물(대본 표, 컷 리스트, 프롬프트)로 낸다.', '{지침}', 'manual'),
('all', '칭찬보다 사실·시장성·실행 가능성으로 판단하고, 약점과 리스크를 먼저 말한다.', '{지침}', 'manual'),
('all', '여러 채널과 프로젝트를 하나의 자산으로 본다: 한 작업물이 쇼츠·홈페이지·쇼핑몰·강의에 어떻게 재사용되는지 함께 제시.', '{지침,자산연결}', 'manual'),
('ad_plan', '제품 광고는 기획, 대사, 연출의 완성도를 우선한다(화려한 효과보다 메시지 명확성).', '{지침}', 'manual'),
('ad_plan', '영상·광고 제안에는 최신 사례와 자료 조사를 근거로 붙인다.', '{지침,리서치}', 'manual'),
('image_prompt', '이미지는 고급스럽고 현실적인 연출과 강한 시각적 상상력을 함께 적용한다.', '{지침}', 'manual'),
('image_prompt', 'AI 이미지 안의 한글은 틀리기 쉬우므로 글자는 후처리(편집기 단어 카드)로 넣는다.', '{한글,편집}', 'manual'),
('shorts_script', 'Kling 5초 클립 + 편집 단계의 단어 확대 카드 조합이 크레딧 대비 효율이 좋았다(EP01 편의점).', '{kling,한글산책}', 'metric'),
('lecture', '강의용 콘텐츠는 채널 안에서 공유·재활용될 수 있게 소단원으로 쪼갠다.', '{지침}', 'manual');
